document.addEventListener('DOMContentLoaded', function () {
  const companiesContainer = document.querySelector('.companies-listing .jet-listing-grid__items');
  const cards = companiesContainer?.querySelectorAll('.jet-listing-grid__item') || [];
  const cardsPerPage = 12;
  const totalPages = Math.ceil(cards.length / cardsPerPage);
  let currentPage = 1;

  function showPage(page) {
    cards.forEach((card, index) => {
      const start = (page - 1) * cardsPerPage;
      const end = page * cardsPerPage;
      card.style.display = index >= start && index < end ? 'block' : 'none';
    });
    renderPagination();
  }

  function renderPagination() {
    let paginationNumbers = '';

    function addPageButton(page) {
      paginationNumbers += `<button class="pagination-page${page === currentPage ? ' active' : ''}" data-page="${page}">${page}</button>`;
    }

    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) {
        addPageButton(i);
      }
    } else {
      addPageButton(1);
      addPageButton(2);

      if (currentPage > 4) {
        paginationNumbers += '<span class="pagination-ellipsis">...</span>';
      }

      const startPage = Math.max(3, currentPage - 1);
      const endPage = Math.min(totalPages - 2, currentPage + 1);

      for (let i = startPage; i <= endPage; i++) {
        addPageButton(i);
      }

      if (currentPage < totalPages - 3) {
        paginationNumbers += '<span class="pagination-ellipsis">...</span>';
      }

      addPageButton(totalPages - 1);
      addPageButton(totalPages);
    }

    const paginationHTML = `
      <button class="pagination-prev"${currentPage === 1 ? ' disabled' : ''}><span style="margin-right: 6px"><</span>Prev</button>
      <div class="paginations">${paginationNumbers}</div>
      <button class="pagination-next"${currentPage === totalPages ? ' disabled' : ''}>Next<span style="margin-left: 6px">></span></button>
    `;

    const paginationWrapper = companiesContainer.parentElement.querySelector('.custom-pagination') || document.createElement('div');
    paginationWrapper.className = 'custom-pagination';
    paginationWrapper.innerHTML = paginationHTML;

    if (!companiesContainer.parentElement.contains(paginationWrapper)) {
      companiesContainer.parentElement.appendChild(paginationWrapper);
    }

    addPaginationEvents();
  }

  function addPaginationEvents() {
    const pageButtons = document.querySelectorAll('.custom-pagination .pagination-page');
    const prevButton = document.querySelector('.custom-pagination .pagination-prev');
    const nextButton = document.querySelector('.custom-pagination .pagination-next');

    pageButtons.forEach(button => {
      button.addEventListener('click', () => {
        const page = parseInt(button.getAttribute('data-page'), 10);
        currentPage = page;
        showPage(currentPage);
      });
    });

    prevButton?.addEventListener('click', () => {
      if (currentPage > 1) {
        currentPage--;
        showPage(currentPage);
      }
    });

    nextButton?.addEventListener('click', () => {
      if (currentPage < totalPages) {
        currentPage++;
        showPage(currentPage);
      }
    });
  }

  if (cards.length > 0) {
    showPage(currentPage);
  }
});
